mapper.select:
SELECT

FROM sys_monthly_inspection_task t
LEFT JOIN sys_user gl ON t.group_leader_id = gl.id AND gl.deleted = 0
LEFT JOIN sys_user dl ON t.deputy_leader_id = dl.id AND dl.deleted = 0
LEFT JOIN sys_dept d ON t.department_id = d.id AND d.deleted = 0
LEFT JOIN sys_dictionary p ON t.profession_id = p.dict_value AND p.dict_type = '专业' AND p.deleted = 0
LEFT JOIN sys_user cu ON t.create_user_id = cu.id AND cu.deleted = 0
WHERE t.deleted = 0

    AND t.group_leader_id = #{groupLeaderId}


    AND t.deputy_leader_id = #{deputyLeaderId}


    AND t.department_id = #{departmentId}


    AND t.profession_id = #{professionId}


    AND t.status = #{status}


    AND t.inspection_time LIKE CONCAT('%', #{inspectionTime}, '%')

ORDER BY t.create_time DESC

SELECT d.name as department_name, COUNT(t.id) as count FROM sys_monthly_inspection_task t LEFT JOIN sys_dept d ON t.department_id = d.id AND d.deleted = 0 WHERE t.deleted = 0
AND t.status = #{status}
GROUP BY t.department_id, d.name ORDER BY count DESC

SELECT p.name as profession_name, COUNT(t.id) as count FROM sys_monthly_inspection_task t WHERE t.deleted = 0
AND t.status = #{status}
GROUP BY t.profession_id, p.name ORDER BY count DESC

